using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using Newtonsoft.Json.Linq;using SpatialWallpaper.Supervision;using SpatialWallpaper.Supervision.Broker;using SpatialWallpaper.Sdk.Capabilities;
static class MiniShotSaveMigrationChecks {
 static int checks;static void Yes(bool value,string name){if(!value)throw new Exception(name);checks++;}static void No(Action action,string name){try{action();}catch(Exception e)when(e is InvalidDataException||e is InvalidOperationException||e is IOException||e is ArgumentException){checks++;return;}throw new Exception("accepted "+name);}
 static BrokerSession Session(Guid id,bool preview=false)=>new BrokerSession(new AttemptReceipt(Guid.NewGuid(),Guid.NewGuid(),id,LegacyMiniShotIdentity.Build,Guid.NewGuid(),1),preview,new[]{"private-storage"});
 static int Main(string[] args){try{
  string content=Path.Combine(args[0],"c"),data=Path.Combine(args[0],"d"),archive=args[1],oldRoot=Path.Combine(content,"sdk-runtime/backend/storage");Guid old=Guid.NewGuid(),revision=Guid.NewGuid();var session=Session(old);var values=Enumerable.Range(1,10).ToDictionary(i=>"minishot.v1.target-"+i.ToString("00"),i=>Encoding.UTF8.GetBytes("hit"));Directory.CreateDirectory(args[0]);
  using(var store=new PrivateStore(oldRoot)){
   store.Commit(session,0,values);store.Commit(Session(old,true),0,new Dictionary<string,byte[]>{{"minishot.v1.target-01",Encoding.UTF8.GetBytes("hit")}});string source=Path.Combine(oldRoot,"live-"+old.ToString("N"),"state.bin");byte[] before=File.ReadAllBytes(source);var acl=Directory.GetAccessControl(oldRoot).GetSecurityDescriptorBinaryForm();
   var receipt=MiniShotSaveMigrationHost.Migrate(content,data,old,revision,archive);Yes((string)receipt["status"]=="imported"&&(int)receipt["hit_count"]==10,"all ten original hit keys imported");Yes((string)receipt["source_work_id"]==old.ToString("D")&&(string)receipt["source_revision_id"]==revision.ToString("D")&&(string)receipt["source_archive_sha256"]==LegacyMiniShotIdentity.ArchiveSha256,"source binding recorded");Yes(File.ReadAllBytes(source).SequenceEqual(before)&&Directory.GetAccessControl(oldRoot).GetSecurityDescriptorBinaryForm().SequenceEqual(acl),"old live files and root ACL remain unchanged while original writer owns store");Yes(store.Read(session).Version==1&&store.Read(session).Keys.Length==10,"old revision session remains readable");
   var imported=PrivateStore.ReadMigrationSnapshot(Path.Combine(data,"native-private-storage","live-"+Guid.Parse(LegacyMiniShotIdentity.NativeWork).ToString("N")));Yes(imported.Version==1&&imported.Keys.Length==11&&imported.Get("minishot.v1.target-10").SequenceEqual(Encoding.UTF8.GetBytes("hit")),"real native private-store snapshot contains migrated hits");Yes(JObject.Parse(Encoding.UTF8.GetString(imported.Get("migration.minishot.schema4")))["source_save_sha256"].Type==JTokenType.String,"durable migration provenance is bound to source snapshot");Yes(File.Exists((string)receipt["receipt_file"]),"public result receipt persisted");
   string target=Path.Combine(data,"native-private-storage","live-"+Guid.Parse(LegacyMiniShotIdentity.NativeWork).ToString("N"),"state.bin");byte[] targetBefore=File.ReadAllBytes(target);No(()=>MiniShotSaveMigrationHost.Migrate(content,data,old,revision,archive),"existing native save never overwritten");Yes(File.ReadAllBytes(target).SequenceEqual(targetBefore),"rejected repeat leaves native bytes identical");
   string wrongArchive=Path.Combine(args[0],"wrong.spatial");File.WriteAllText(wrongArchive,"not original");No(()=>MiniShotSaveMigrationHost.Migrate(content,Path.Combine(args[0],"wrong"),old,revision,wrongArchive),"untrusted package cannot authorize cross-work copy");No(()=>MiniShotSaveMigrationHost.Migrate(content,Path.Combine(args[0],"none"),Guid.NewGuid(),revision,archive),"missing source save rejected");No(()=>MiniShotSaveMigrationHost.Migrate(content,Path.Combine(args[0],"empty"),old,Guid.Empty,archive),"missing exact revision rejected");
   var other=Guid.NewGuid();store.Commit(Session(other),0,new Dictionary<string,byte[]>{{"foreign",Encoding.UTF8.GetBytes("hit")}});No(()=>MiniShotSaveMigrationHost.Migrate(content,Path.Combine(args[0],"foreign"),other,revision,archive),"unexpected keys rejected");var invalid=Guid.NewGuid();store.Commit(Session(invalid),0,new Dictionary<string,byte[]>{{"minishot.v1.target-01",Encoding.UTF8.GetBytes("forged")}});No(()=>MiniShotSaveMigrationHost.Migrate(content,Path.Combine(args[0],"invalid"),invalid,revision,archive),"invalid target state rejected");
   var previewOnly=Guid.NewGuid();store.Commit(Session(previewOnly,true),0,new Dictionary<string,byte[]>{{"minishot.v1.target-01",Encoding.UTF8.GetBytes("hit")}});No(()=>MiniShotSaveMigrationHost.Migrate(content,Path.Combine(args[0],"preview"),previewOnly,revision,archive),"preview namespace cannot seed live progress");
   var broken=Guid.NewGuid();store.Commit(Session(broken),0,values);string brokenFile=Path.Combine(oldRoot,"live-"+broken.ToString("N"),"state.bin");byte[] corrupt=File.ReadAllBytes(brokenFile);corrupt[20]^=1;File.WriteAllBytes(brokenFile,corrupt);No(()=>MiniShotSaveMigrationHost.Migrate(content,Path.Combine(args[0],"broken"),broken,revision,archive),"checksum corruption rejected");
   var config=new JObject{{"content_root",content},{"data_root",Path.Combine(args[0],"cli")},{"source_work",old.ToString("D")},{"source_revision",revision.ToString("D")},{"archive",archive}};File.WriteAllText(Path.Combine(args[0],"cli.json"),config.ToString());
  }
  Console.WriteLine("MiniShot migration checks passed: "+checks);return 0;
 }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
